class Solution:
    def loudAndRich(self, richer: list[list[int]], quiet: list[int]) -> list[int]:
        n = len(quiet)
        parents = [[] for _ in range(n)]
        for a, b in richer:
            parents[b].append(a)
        ans = []
        for x in range(n):
            best = x; seen = {x}; stack = [x]
            while stack:
                u = stack.pop()
                if quiet[u] < quiet[best]:
                    best = u
                for p in parents[u]:
                    if p not in seen:
                        seen.add(p); stack.append(p)
            ans.append(best)
        return ans

