class Solution:
    def loudAndRich(self, richer: list[list[int]], quiet: list[int]) -> list[int]:
        n = len(quiet)
        parents = [[] for _ in range(n)]
        for a, b in richer:
            parents[b].append(a)
        memo = [-1] * n
        def dfs(x):
            if memo[x] != -1:
                return memo[x]
            best = x
            for p in parents[x]:
                cand = dfs(p)
                if quiet[cand] < quiet[best]:
                    best = cand
            memo[x] = best
            return best
        return [dfs(i) for i in range(n)]

