class Solution:
    def loudAndRich(self, richer: list[list[int]], quiet: list[int]) -> list[int]:
        from collections import deque
        n = len(quiet)
        g = [[] for _ in range(n)]
        indeg = [0] * n
        for a, b in richer:
            g[a].append(b); indeg[b] += 1
        ans = list(range(n))
        q = deque([i for i in range(n) if indeg[i] == 0])
        while q:
            u = q.popleft()
            for v in g[u]:
                if quiet[ans[u]] < quiet[ans[v]]:
                    ans[v] = ans[u]
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        return ans

